function drawField(f){const key=fkey(f),current=formEdits.has(key)?formEdits.get(key):f.value;let el;if(f.type==='Btn'&&f.radioButton){el=document.createElement('input');el.type='radio';el.className='nativeField radio';el.name='radio_'+(f.name||f.id);el.checked=String(current)===String(f.buttonValue)||current===true;el.onchange=()=>{if(el.checked){pushHistory();formEdits.set(key,f.buttonValue||'Yes');markDirty()}}}else if(f.type==='Btn'){el=document.createElement('input');el.type='checkbox';el.className='nativeField checkbox';el.checked=!!current&&current!=='Off';el.onchange=()=>{pushHistory();formEdits.set(key,el.checked);markDirty()}}else if(f.type==='Ch'&&f.options?.length){el=document.createElement('select');el.className='nativeField';for(const op of f.options){const opt=document.createElement('option');opt.value=op.exportValue??op.displayValue??op;opt.textContent=op.displayValue??op.exportValue??op;el.appendChild(opt)}el.value=current||'';el.onchange=()=>{pushHistory();formEdits.set(key,el.value);markDirty()}}else{el=document.createElement('input');el.type='text';el.className='nativeField';el.value=current||'';el.onchange=()=>{pushHistory();formEdits.set(key,el.value);markDirty()}}el.title=f.name||'PDF field';Object.assign(el.style,{left:f.x+'px',top:f.y+'px',width:Math.max(12,f.w)+'px',height:Math.max(12,f.h)+'px'});interaction.appendChild(el)}
