const APP_TABS=['pdf','templates','tasks','links','notes','queue','composer','handover','home'];
function setAppTab(name){
  if(!APP_TABS.includes(name)) name='pdf';
  const isPdf=name==='pdf';
  const pdfPanel=$('#pdfPanel'), pdfFooter=$('#pdfFooter'), pdfActions=$('#pdfHeaderActions');
  if(pdfPanel){pdfPanel.hidden=!isPdf;pdfPanel.classList.toggle('is-active',isPdf)}
  if(pdfFooter){pdfFooter.hidden=!isPdf;pdfFooter.classList.toggle('is-active',isPdf)}
  if(pdfActions) pdfActions.hidden=!isPdf;
  APP_TABS.filter(n=>n!=='pdf').forEach(n=>{const el=$('#'+n+'Panel');if(!el)return;const active=name===n;el.hidden=!active;el.classList.toggle('is-active',active)});
  document.querySelectorAll('.appTab').forEach(b=>{const active=b.dataset.appTab===name;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active))});
  document.body.dataset.activeTab=name;
  try{sessionStorage.setItem('osama-active-tab',name)}catch{}
  if(name==='templates')renderTemplates();
  if(name==='tasks')renderTasks();
  if(name==='links')renderLinks();
  if(name==='queue')renderQueue();
  if(name==='composer')renderComposer();
  if(name==='handover')generateHandover();
  if(name==='home')renderDashboard();
  window.scrollTo({top:0,left:0,behavior:'auto'});
}
