function fillTemplate(t){let body=t.body;for(const key of placeholders(body)){const val=prompt(`Enter ${key.replace(/_/g,' ')}:`,'');if(val===null)return null;body=body.split('{{'+key+'}}').join(val);body=body.replace(new RegExp('{{\\s*'+key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\s*}}','g'),val)}return body}
