function updateTemplateFilters(items){const sel=$('#templateCategory'),cur=sel.value,cats=[...new Set(items.map(x=>x.category).filter(Boolean))].sort();sel.innerHTML='<option value="">All categories</option>'+cats.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');if(cats.includes(cur))sel.value=cur;$('#categorySuggestions').innerHTML=cats.map(c=>`<option value="${esc(c)}"></option>`).join('')}
function renderTemplates(){let all=loadTemplates();updateTemplateFilters(all);const q=$('#templateSearch').value.trim().toLowerCase(),cat=$('#templateCategory').value,fav=$('#favoritesOnly').checked;let items=all.filter(t=>(!q||(t.name+' '+t.category+' '+t.body).toLowerCase().includes(q))&&(!cat||t.category===cat)&&(!fav||t.favorite));items.sort((a,b)=>(Number(b.favorite)-Number(a.favorite))||((b.updatedAt||0)-(a.updatedAt||0)));$('#templateCards').innerHTML=items.length?items.map(t=>`<article class="templateCard"><div class="templateCardHead"><div><h3>${esc(t.name)}</h3><span class="categoryPill">${esc(t.category||'General')}</span></div><button class="starBtn ${t.favorite?'on':''}" data-fav-template="${t.id}" title="Favorite">${t.favorite?'★':'☆'}</button></div><pre>${esc(t.body)}</pre><div class="templateActions"><button class="primary" data-copy-template="${t.id}">⧉ Copy</button><button data-edit-template="${t.id}">✎ Edit</button><button data-dup-template="${t.id}">Duplicate</button><button class="dangerText" data-del-template="${t.id}">Delete</button></div></article>`).join(''):'<div class="emptyTemplates"><h3>No templates here yet</h3><p>Add your first reusable email reply.</p></div>';
document.querySelectorAll('[data-copy-template]').forEach(b=>b.onclick=()=>copyTemplate(loadTemplates().find(t=>t.id===b.dataset.copyTemplate)));document.querySelectorAll('[data-edit-template]').forEach(b=>b.onclick=()=>openTemplateModal(loadTemplates().find(t=>t.id===b.dataset.editTemplate)));document.querySelectorAll('[data-dup-template]').forEach(b=>b.onclick=()=>{const a=loadTemplates(),t=a.find(x=>x.id===b.dataset.dupTemplate);if(!t)return;a.unshift({...t,id:crypto.randomUUID(),name:t.name+' (Copy)',favorite:false,updatedAt:Date.now()});saveTemplates(a);renderTemplates()});document.querySelectorAll('[data-fav-template]').forEach(b=>b.onclick=()=>{const a=loadTemplates(),t=a.find(x=>x.id===b.dataset.favTemplate);if(t){t.favorite=!t.favorite;t.updatedAt=Date.now();saveTemplates(a);renderTemplates()}});document.querySelectorAll('[data-del-template]').forEach(b=>b.onclick=()=>{if(confirm('Delete this email template?')){saveTemplates(loadTemplates().filter(t=>t.id!==b.dataset.delTemplate));renderTemplates()}})}
function openTemplateModal(t=null){editingTemplateId=t?.id||null;$('#templateModalTitle').textContent=t?'Edit Template':'Add Template';$('#tplName').value=t?.name||'';$('#tplCategory').value=t?.category||'';$('#tplBody').value=t?.body||'';$('#templateModal').hidden=false;setTimeout(()=>$('#tplName').focus(),0)}
function closeTemplateModal(){$('#templateModal').hidden=true;editingTemplateId=null}
$('#addTemplate').onclick=()=>openTemplateModal();$('#closeTemplateModal').onclick=closeTemplateModal;$('#cancelTemplate').onclick=closeTemplateModal;$('#templateModal').onclick=e=>{if(e.target===$('#templateModal'))closeTemplateModal()};
$('#saveTemplate').onclick=()=>{const name=$('#tplName').value.trim(),body=$('#tplBody').value.trim(),category=$('#tplCategory').value.trim()||'General';if(!name){alert('Please add a template name.');return $('#tplName').focus()}if(!body){alert('Please add the email text.');return $('#tplBody').focus()}const a=loadTemplates(),now=Date.now();if(editingTemplateId){const t=a.find(x=>x.id===editingTemplateId);if(t)Object.assign(t,{name,body,category,updatedAt:now})}else a.unshift({id:crypto.randomUUID(),name,body,category,favorite:false,createdAt:now,updatedAt:now});saveTemplates(a);closeTemplateModal();renderTemplates()};
$('#templateSearch').oninput=renderTemplates;$('#templateCategory').onchange=renderTemplates;$('#favoritesOnly').onchange=renderTemplates;window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#templateModal').hidden)closeTemplateModal()});


// V9 workspace modules
const TASK_KEY='osama-automation-tasks-v1', LINK_KEY='osama-automation-links-v1', NOTES_KEY='osama-automation-notes-v1';
const todayKey=()=>new Date().toISOString().slice(0,10);
const readLocal=(k,d=[])=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(d))}catch{return d}};
const writeLocal=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
let editingTaskId=null,editingLinkId=null;
function ensureRecurring(){const a=readLocal(TASK_KEY),today=todayKey();let changed=false;for(const t of [...a])if(t.recurring&&t.date!==today&&!a.some(x=>x.recurringSource===t.id&&x.date===today)){a.unshift({...t,id:crypto.randomUUID(),date:today,done:false,doneAt:null,recurring:false,recurringSource:t.recurringSource||t.id,createdAt:Date.now()});changed=true}if(changed)writeLocal(TASK_KEY,a)}
function renderTasks(){ensureRecurring();const all=readLocal(TASK_KEY),q=$('#taskSearch').value.trim().toLowerCase(),f=$('#taskFilter').value,today=todayKey();let items=all.filter(t=>(!q||(t.title+' '+(t.notes||'')).toLowerCase().includes(q))&&(f==='all'||(f==='done'?t.done:!t.done)));items.sort((a,b)=>(Number(a.done)-Number(b.done))||(Number(b.priority==='Urgent')-Number(a.priority==='Urgent'))||String(a.time||'99:99').localeCompare(String(b.time||'99:99')));const td=all.filter(t=>t.date===today),done=td.filter(t=>t.done).length;$('#taskProgress').innerHTML=`<b>${done} / ${td.length} completed today</b><div class="progressTrack"><i style="width:${td.length?done/td.length*100:0}%"></i></div>`;$('#taskList').innerHTML=items.length?items.map(t=>`<article class="listCard ${t.done?'done':''}"><button class="doneBtn" data-task-done="${t.id}" title="Mark ${t.done?'pending':'done'}">${t.done?'✓':'○'}</button><div class="grow"><b>${esc(t.title)}</b><div class="meta">${esc(t.date||'')} ${t.time?'• '+esc(t.time):''} • ${esc(t.priority||'Normal')}${t.recurring?' • ↻ Daily':''}</div>${t.notes?`<div class="cardNote">${esc(t.notes)}</div>`:''}</div><button data-task-edit="${t.id}">Edit</button><button class="dangerText" data-task-del="${t.id}">Delete</button></article>`).join(''):'<div class="emptyTemplates">No tasks match this view.</div>';document.querySelectorAll('[data-task-done]').forEach(b=>b.onclick=()=>{const a=readLocal(TASK_KEY),t=a.find(x=>x.id===b.dataset.taskDone);if(t){t.done=!t.done;t.doneAt=t.done?Date.now():null;writeLocal(TASK_KEY,a);renderTasks();renderDashboard()}});document.querySelectorAll('[data-task-edit]').forEach(b=>b.onclick=()=>openTask(readLocal(TASK_KEY).find(x=>x.id===b.dataset.taskEdit)));document.querySelectorAll('[data-task-del]').forEach(b=>b.onclick=()=>{if(confirm('Delete this task?')){writeLocal(TASK_KEY,readLocal(TASK_KEY).filter(x=>x.id!==b.dataset.taskDel));renderTasks();renderDashboard()}})}
function openTask(t=null){editingTaskId=t?.id||null;$('#taskModalTitle').textContent=t?'Edit Task':'Add Task';$('#taskTitle').value=t?.title||'';$('#taskPriority').value=t?.priority||'Normal';$('#taskTime').value=t?.time||'';$('#taskRecurring').checked=!!t?.recurring;$('#taskNotes').value=t?.notes||'';$('#taskModal').hidden=false;setTimeout(()=>$('#taskTitle').focus(),0)}
$('#addTask').onclick=()=>openTask();$('#saveTask').onclick=()=>{const title=$('#taskTitle').value.trim();if(!title)return alert('Please add a task.');const a=readLocal(TASK_KEY),data={title,priority:$('#taskPriority').value,time:$('#taskTime').value,recurring:$('#taskRecurring').checked,notes:$('#taskNotes').value.trim(),date:todayKey(),updatedAt:Date.now()};if(editingTaskId){const t=a.find(x=>x.id===editingTaskId);if(t)Object.assign(t,data)}else a.unshift({id:crypto.randomUUID(),done:false,createdAt:Date.now(),...data});writeLocal(TASK_KEY,a);$('#taskModal').hidden=true;editingTaskId=null;renderTasks();renderDashboard()};$('#taskFilter').onchange=renderTasks;$('#taskSearch').oninput=renderTasks;$('#clearDone').onclick=()=>{if(confirm('Remove all completed tasks?')){writeLocal(TASK_KEY,readLocal(TASK_KEY).filter(t=>!t.done));renderTasks();renderDashboard()}};$('#carryTasks').onclick=()=>{const a=readLocal(TASK_KEY),today=todayKey();let n=0;for(const t of a)if(!t.done&&t.date!==today){t.date=today;n++}writeLocal(TASK_KEY,a);renderTasks();alert(n?`${n} task(s) moved to today.`:'No pending older tasks.')};
function renderLinks(){const q=$('#linkSearch').value.trim().toLowerCase();let a=readLocal(LINK_KEY).filter(x=>!q||(x.name+' '+x.url).toLowerCase().includes(q));a.sort((x,y)=>Number(y.favorite)-Number(x.favorite)||(y.updatedAt||0)-(x.updatedAt||0));$('#linkList').innerHTML=a.length?a.map(x=>`<article class="linkCard"><div class="grow"><b>${x.favorite?'★ ':''}${esc(x.name)}</b><div class="meta">${esc(x.url)}</div></div><a class="buttonLink primary" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Open</a><button data-link-edit="${x.id}">Edit</button><button class="dangerText" data-link-del="${x.id}">Delete</button></article>`).join(''):'<div class="emptyTemplates">No links saved yet.</div>';document.querySelectorAll('[data-link-edit]').forEach(b=>b.onclick=()=>openLink(readLocal(LINK_KEY).find(x=>x.id===b.dataset.linkEdit)));document.querySelectorAll('[data-link-del]').forEach(b=>b.onclick=()=>{if(confirm('Delete this link?')){writeLocal(LINK_KEY,readLocal(LINK_KEY).filter(x=>x.id!==b.dataset.linkDel));renderLinks();renderDashboard()}})}
function openLink(x=null){editingLinkId=x?.id||null;$('#linkModalTitle').textContent=x?'Edit Link':'Add Link';$('#linkName').value=x?.name||'';$('#linkUrl').value=x?.url||'';$('#linkFavorite').checked=!!x?.favorite;$('#linkModal').hidden=false}
$('#addLink').onclick=()=>openLink();$('#saveLink').onclick=()=>{const name=$('#linkName').value.trim(),url=$('#linkUrl').value.trim();if(!name||!url)return alert('Please add a name and URL.');let u;try{u=new URL(url);if(!['http:','https:'].includes(u.protocol))throw 0}catch{return alert('Please enter a valid http/https URL.')}const a=readLocal(LINK_KEY),data={name,url:u.href,favorite:$('#linkFavorite').checked,updatedAt:Date.now()};if(editingLinkId){const x=a.find(y=>y.id===editingLinkId);if(x)Object.assign(x,data)}else a.unshift({id:crypto.randomUUID(),createdAt:Date.now(),...data});writeLocal(LINK_KEY,a);$('#linkModal').hidden=true;editingLinkId=null;renderLinks();renderDashboard()};$('#linkSearch').oninput=renderLinks;
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{$('#'+b.dataset.close).hidden=true});
const notes=$('#quickNotes');notes.value=localStorage.getItem(NOTES_KEY)||'';let notesTimer;notes.oninput=()=>{clearTimeout(notesTimer);$('#notesStatus').textContent='Saving…';notesTimer=setTimeout(()=>{localStorage.setItem(NOTES_KEY,notes.value);$('#notesStatus').textContent='Saved locally';renderDashboard()},250)};$('#copyNotes').onclick=async()=>{try{await navigator.clipboard.writeText(notes.value)}catch{}$('#notesStatus').textContent='Copied'};$('#clearNotes').onclick=()=>{if(confirm('Clear quick notes?')){notes.value='';localStorage.removeItem(NOTES_KEY);$('#notesStatus').textContent='Cleared';renderDashboard()}};
function renderDashboard(){ensureRecurring();const a=readLocal(TASK_KEY),today=todayKey(),td=a.filter(t=>t.date===today),pending=td.filter(t=>!t.done),templates=loadTemplates(),links=readLocal(LINK_KEY),favs=links.filter(x=>x.favorite).slice(0,5);$('#dashboardGrid').innerHTML=`<article class="dashCard"><span>Today</span><strong>${td.filter(t=>t.done).length}/${td.length}</strong><p>tasks completed</p><button data-go="tasks">Open Daily Tasks</button></article><article class="dashCard"><span>Pending</span><strong>${pending.length}</strong><p>${pending.filter(t=>t.priority==='Urgent').length} urgent</p><button data-go="tasks">View pending</button></article><article class="dashCard"><span>Email templates</span><strong>${templates.length}</strong><p>${templates.filter(t=>t.favorite).length} favorites</p><button data-go="templates">Open Templates</button></article><article class="dashCard wide"><span>Favorite links</span>${favs.length?favs.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.name)}</a>`).join(''):'<p>No favorite links yet.</p>'}<button data-go="links">Manage Links</button></article><article class="dashCard wide"><span>Quick Notes</span><p>${esc((notes.value||'No notes saved.').slice(0,180))}</p><button data-go="notes">Open Notes</button></article>`;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>setAppTab(b.dataset.go))}
$('#exportBackup').onclick=()=>{const includeSigs=confirm('Include saved signature images in this backup? Only do this for an authorised work device.');const keys=[TEMPLATE_KEY,TASK_KEY,LINK_KEY,NOTES_KEY];const data={version:9,createdAt:new Date().toISOString(),storage:{}};for(const k of keys)data.storage[k]=localStorage.getItem(k);if(includeSigs){for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&/sig|signature/i.test(k))data.storage[k]=localStorage.getItem(k)}}const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='osama-automation-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),500)};
$('#importBackup').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!d.storage||typeof d.storage!=='object')throw 0;if(!confirm('Import this backup and overwrite matching local workspace data?'))return;for(const [k,v] of Object.entries(d.storage))if(typeof v==='string')localStorage.setItem(k,v);notes.value=localStorage.getItem(NOTES_KEY)||'';renderTemplates();renderTasks();renderLinks();renderDashboard();alert('Backup restored.')}catch{alert('This does not look like a valid Osama Automation backup.')}finally{e.target.value=''}};
setAppTab('home');renderDashboard();

// V10 workflow modules - no login, cloud storage, or external-system integration.
const QUEUE_KEY='osama-automation-queue-v1', SNIPPET_KEY='osama-automation-snippets-v1', PREF_KEY='osama-automation-preferences-v1';
let editingCaseId=null,editingSnippetId=null,queueDueOnly=false,composerTemplateId='';
const checklistTemplates={external:['Referral checked','Required details checked','Payment route checked','PDF prepared','Referral sent','Tracker updated','Response received','Follow-up completed'],booking:['Request checked','Required details available','Availability checked','Booking completed','Confirmation prepared']};
const fmtDate=v=>{if(!v)return 'No follow-up';const d=new Date(v);return Number.isNaN(+d)?v:d.toLocaleString()};
function renderQueue(){const all=readLocal(QUEUE_KEY),q=$('#queueSearch').value.trim().toLowerCase(),st=$('#queueStatus').value,pr=$('#queuePriority').value,now=Date.now();let items=all.filter(c=>(!q||(c.title+' '+(c.notes||'')+' '+(c.owner||'')+' '+(c.modality||'')).toLowerCase().includes(q))&&(!st||c.status===st)&&(!pr||c.priority===pr)&&(!queueDueOnly||(c.status!=='Completed'&&c.followup&&new Date(c.followup).getTime()<=now)));items.sort((a,b)=>Number(a.status==='Completed')-Number(b.status==='Completed')||Number(b.priority==='Urgent')-Number(a.priority==='Urgent')||((a.followup?new Date(a.followup).getTime():Infinity)-(b.followup?new Date(b.followup).getTime():Infinity)));const open=all.filter(c=>c.status!=='Completed'),due=open.filter(c=>c.followup&&new Date(c.followup).getTime()<=now);$('#queueStats').innerHTML=`<b>${open.length} open • ${due.length} due/overdue • ${open.filter(c=>c.priority==='Urgent').length} urgent</b>`;$('#showDue').classList.toggle('active',queueDueOnly);$('#queueList').innerHTML=items.length?items.map(c=>{const dueNow=c.status!=='Completed'&&c.followup&&new Date(c.followup).getTime()<=now;const checks=c.checklist||[];const checked=checks.filter(x=>x.done).length;return `<article class="listCard queueCard ${dueNow?'overdue':''}"><div class="grow"><div class="queueTitle"><b>${esc(c.title)}</b><span class="statusPill">${esc(c.status)}</span>${c.priority==='Urgent'?'<span class="urgentPill">Urgent</span>':''}</div><div class="meta">${esc(c.modality||'General')} • Owner: ${esc(c.owner||'Unassigned')} • Follow-up: ${esc(fmtDate(c.followup))}${checks.length?` • Checklist ${checked}/${checks.length}`:''}</div>${c.notes?`<div class="cardNote">${esc(c.notes)}</div>`:''}${checks.length?`<div class="caseChecks">${checks.map((x,i)=>`<label><input type="checkbox" data-case-check="${c.id}:${i}" ${x.done?'checked':''}> ${esc(x.label)}</label>`).join('')}</div>`:''}</div><button data-case-follow="${c.id}">Follow-up</button><button data-case-edit="${c.id}">Edit</button><button data-case-complete="${c.id}">${c.status==='Completed'?'Reopen':'✓ Complete'}</button><button class="dangerText" data-case-del="${c.id}">Delete</button></article>`}).join(''):'<div class="emptyTemplates">No cases match this view.</div>';
 document.querySelectorAll('[data-case-check]').forEach(el=>el.onchange=()=>{const [id,idx]=el.dataset.caseCheck.split(':');const a=readLocal(QUEUE_KEY),c=a.find(x=>x.id===id);if(c?.checklist?.[+idx]){c.checklist[+idx].done=el.checked;c.updatedAt=Date.now();writeLocal(QUEUE_KEY,a);renderQueue();renderDashboard()}});document.querySelectorAll('[data-case-edit]').forEach(b=>b.onclick=()=>openCase(readLocal(QUEUE_KEY).find(x=>x.id===b.dataset.caseEdit)));document.querySelectorAll('[data-case-follow]').forEach(b=>b.onclick=()=>{const a=readLocal(QUEUE_KEY),c=a.find(x=>x.id===b.dataset.caseFollow);if(!c)return;const v=prompt('Next follow-up date/time (YYYY-MM-DD HH:MM):',c.followup?c.followup.replace('T',' '):'');if(v===null)return;const parsed=v.trim()?new Date(v.trim().replace(' ','T')):null;if(v.trim()&&Number.isNaN(+parsed))return alert('Invalid date/time.');c.followup=parsed?new Date(parsed.getTime()-parsed.getTimezoneOffset()*60000).toISOString().slice(0,16):'';c.updatedAt=Date.now();writeLocal(QUEUE_KEY,a);renderQueue();renderDashboard()});document.querySelectorAll('[data-case-complete]').forEach(b=>b.onclick=()=>{const a=readLocal(QUEUE_KEY),c=a.find(x=>x.id===b.dataset.caseComplete);if(c){c.status=c.status==='Completed'?'New':'Completed';c.completedAt=c.status==='Completed'?Date.now():null;c.updatedAt=Date.now();writeLocal(QUEUE_KEY,a);renderQueue();renderDashboard()}});document.querySelectorAll('[data-case-del]').forEach(b=>b.onclick=()=>{if(confirm('Delete this case?')){writeLocal(QUEUE_KEY,readLocal(QUEUE_KEY).filter(x=>x.id!==b.dataset.caseDel));renderQueue();renderDashboard()}})}
function openCase(c=null){editingCaseId=c?.id||null;$('#caseModalTitle').textContent=c?'Edit Case':'Add Case';$('#caseTitle').value=c?.title||'';$('#caseStatus').value=c?.status||'New';$('#casePriority').value=c?.priority||'Normal';$('#caseOwner').value=c?.owner||'';$('#caseModality').value=c?.modality||'General';$('#caseFollowup').value=c?.followup||'';$('#caseNotes').value=c?.notes||'';$('#caseChecklistType').value=c?.checklistType||'';$('#caseModal').hidden=false;setTimeout(()=>$('#caseTitle').focus(),0)}
$('#addCase').onclick=()=>openCase();$('#saveCase').onclick=()=>{const title=$('#caseTitle').value.trim();if(!title)return alert('Add a reference or description.');const a=readLocal(QUEUE_KEY),type=$('#caseChecklistType').value,data={title,status:$('#caseStatus').value,priority:$('#casePriority').value,owner:$('#caseOwner').value.trim(),modality:$('#caseModality').value,followup:$('#caseFollowup').value,notes:$('#caseNotes').value.trim(),checklistType:type,updatedAt:Date.now()};if(editingCaseId){const c=a.find(x=>x.id===editingCaseId);if(c){const oldType=c.checklistType;Object.assign(c,data);if(type!==oldType)c.checklist=(checklistTemplates[type]||[]).map(label=>({label,done:false}))}}else a.unshift({id:crypto.randomUUID(),createdAt:Date.now(),checklist:(checklistTemplates[type]||[]).map(label=>({label,done:false})),...data});writeLocal(QUEUE_KEY,a);$('#caseModal').hidden=true;editingCaseId=null;renderQueue();renderDashboard()};$('#queueSearch').oninput=renderQueue;$('#queueStatus').onchange=renderQueue;$('#queuePriority').onchange=renderQueue;$('#showDue').onclick=()=>{queueDueOnly=!queueDueOnly;renderQueue()};
function loadSnippets(){return readLocal(SNIPPET_KEY)}function renderComposer(){const templates=loadTemplates();$('#composerTemplate').innerHTML='<option value="">Choose template…</option>'+templates.map(t=>`<option value="${t.id}" ${t.id===composerTemplateId?'selected':''}>${esc(t.name)}</option>`).join('');renderSnippets();if(composerTemplateId)loadComposerTemplate(composerTemplateId)}
function composePlaceholders(body){return [...new Set([...body.matchAll(/{{\s*([^{}]+?)\s*}}/g)].map(m=>m[1].trim()))]}
function loadComposerTemplate(id){composerTemplateId=id;const t=loadTemplates().find(x=>x.id===id);if(!t){$('#composerFields').innerHTML='';return}const fields=composePlaceholders(t.body);$('#composerFields').innerHTML=fields.map(k=>`<label>${esc(k.replaceAll('_',' '))}<input data-compose-field="${esc(k)}" placeholder="${esc(k.replaceAll('_',' '))}"></label>`).join('');$('#composerPreview').value=t.body;document.querySelectorAll('[data-compose-field]').forEach(i=>i.oninput=updateComposerPreview)}
function updateComposerPreview(){const t=loadTemplates().find(x=>x.id===composerTemplateId);if(!t)return;let body=t.body;document.querySelectorAll('[data-compose-field]').forEach(i=>{body=body.replace(new RegExp('{{\\s*'+i.dataset.composeField.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\s*}}','g'),i.value)});$('#composerPreview').value=body}
$('#composerTemplate').onchange=e=>{composerTemplateId=e.target.value;loadComposerTemplate(composerTemplateId)};$('#copySubject').onclick=()=>copyText($('#composerSubject').value,'Subject copied');$('#copyBody').onclick=()=>copyText($('#composerPreview').value,'Email copied');$('#clearComposer').onclick=()=>{$('#composerSubject').value='';$('#composerPreview').value='';composerTemplateId='';$('#composerTemplate').value='';$('#composerFields').innerHTML=''};
async function copyText(v,msg){if(!v)return;try{await navigator.clipboard.writeText(v);alert(msg)}catch{alert('Copy failed. Select the text and copy manually.')}}
function renderSnippets(){const a=loadSnippets();$('#snippetList').innerHTML=a.length?a.map(s=>`<div class="snippet"><button data-snippet-use="${s.id}" title="Insert snippet">+ ${esc(s.name)}</button><button data-snippet-edit="${s.id}">Edit</button><button class="dangerText" data-snippet-del="${s.id}">×</button></div>`).join(''):'<div class="mini">No snippets saved yet.</div>';document.querySelectorAll('[data-snippet-use]').forEach(b=>b.onclick=()=>{const s=loadSnippets().find(x=>x.id===b.dataset.snippetUse);if(s){const ta=$('#composerPreview'),start=ta.selectionStart??ta.value.length;ta.value=ta.value.slice(0,start)+(start?'\n':'')+s.body+ta.value.slice(start);ta.focus()}});document.querySelectorAll('[data-snippet-edit]').forEach(b=>b.onclick=()=>openSnippet(loadSnippets().find(x=>x.id===b.dataset.snippetEdit)));document.querySelectorAll('[data-snippet-del]').forEach(b=>b.onclick=()=>{if(confirm('Delete snippet?')){writeLocal(SNIPPET_KEY,loadSnippets().filter(x=>x.id!==b.dataset.snippetDel));renderSnippets()}})}
function openSnippet(s=null){editingSnippetId=s?.id||null;$('#snippetModalTitle').textContent=s?'Edit Snippet':'Add Snippet';$('#snippetName').value=s?.name||'';$('#snippetBody').value=s?.body||'';$('#snippetModal').hidden=false}$('#addSnippet').onclick=()=>openSnippet();$('#saveSnippet').onclick=()=>{const name=$('#snippetName').value.trim(),body=$('#snippetBody').value.trim();if(!name||!body)return alert('Add a name and text.');const a=loadSnippets();if(editingSnippetId){const s=a.find(x=>x.id===editingSnippetId);if(s)Object.assign(s,{name,body,updatedAt:Date.now()})}else a.unshift({id:crypto.randomUUID(),name,body,createdAt:Date.now()});writeLocal(SNIPPET_KEY,a);$('#snippetModal').hidden=true;editingSnippetId=null;renderSnippets()};
function generateHandover(){const q=readLocal(QUEUE_KEY),open=q.filter(c=>c.status!=='Completed'),due=open.filter(c=>c.followup&&new Date(c.followup).getTime()<=Date.now()),tasks=readLocal(TASK_KEY).filter(t=>t.date===todayKey()),pending=tasks.filter(t=>!t.done);const byStatus={};open.forEach(c=>byStatus[c.status]=(byStatus[c.status]||0)+1);const lines=[`Shift Handover - ${new Date().toLocaleString()}`,'',`Work queue: ${open.length} open | ${due.length} due/overdue | ${open.filter(c=>c.priority==='Urgent').length} urgent`,...Object.entries(byStatus).map(([k,v])=>`- ${k}: ${v}`),'',`Daily tasks: ${tasks.filter(t=>t.done).length}/${tasks.length} completed | ${pending.length} pending`];if(due.length){lines.push('','Due / overdue follow-ups:');due.slice(0,20).forEach(c=>lines.push(`- ${c.title} | ${c.status} | ${c.modality||'General'} | ${fmtDate(c.followup)}`))}if(pending.length){lines.push('','Pending tasks:');pending.slice(0,20).forEach(t=>lines.push(`- ${t.priority==='Urgent'?'URGENT - ':''}${t.title}${t.time?' @ '+t.time:''}`))}$('#handoverText').value=lines.join('\n')}$('#generateHandover').onclick=generateHandover;$('#copyHandover').onclick=()=>copyText($('#handoverText').value,'Handover copied');
// Universal search across local non-PDF workspace data.
let searchTimer;$('#globalSearch').oninput=e=>{clearTimeout(searchTimer);const q=e.target.value.trim().toLowerCase();if(!q){$('#searchModal').hidden=true;return}searchTimer=setTimeout(()=>{const results=[];loadTemplates().forEach(x=>{if((x.name+' '+x.body+' '+x.category).toLowerCase().includes(q))results.push({type:'Template',title:x.name,tab:'templates'})});readLocal(TASK_KEY).forEach(x=>{if((x.title+' '+(x.notes||'')).toLowerCase().includes(q))results.push({type:'Task',title:x.title,tab:'tasks'})});readLocal(LINK_KEY).forEach(x=>{if((x.name+' '+x.url).toLowerCase().includes(q))results.push({type:'Link',title:x.name,tab:'links'})});readLocal(QUEUE_KEY).forEach(x=>{if((x.title+' '+(x.notes||'')+' '+(x.owner||'')).toLowerCase().includes(q))results.push({type:'Case',title:x.title,tab:'queue'})});loadSnippets().forEach(x=>{if((x.name+' '+x.body).toLowerCase().includes(q))results.push({type:'Snippet',title:x.name,tab:'composer'})});$('#searchResults').innerHTML=results.length?results.slice(0,50).map((r,i)=>`<button class="searchResult" data-search-go="${r.tab}"><b>${esc(r.type)}</b><span>${esc(r.title)}</span></button>`).join(''):'<div class="emptyTemplates">No matches.</div>';$('#searchModal').hidden=false;document.querySelectorAll('[data-search-go]').forEach(b=>b.onclick=()=>{$('#searchModal').hidden=true;$('#globalSearch').value='';setAppTab(b.dataset.searchGo)})},180)};
// Theme and density preferences.
function applyPrefs(){const p=readLocal(PREF_KEY,{});document.body.classList.toggle('dark',!!p.dark);document.body.classList.toggle('compact',!!p.compact);$('#themeToggle').textContent=p.dark?'☀':'◐';$('#compactToggle').classList.toggle('active',!!p.compact)}function togglePref(k){const p=readLocal(PREF_KEY,{});p[k]=!p[k];writeLocal(PREF_KEY,p);applyPrefs()}$('#themeToggle').onclick=()=>togglePref('dark');$('#compactToggle').onclick=()=>togglePref('compact');applyPrefs();
// Optional human pre-save checklist; all boxes must be acknowledged before export.
const rawPdfSave=$('#save').onclick;$('#save').onclick=()=>{if(!pdfBytes)return;document.querySelectorAll('.pdfReview').forEach(x=>x.checked=false);$('#pdfCheckModal').hidden=false};$('#confirmPdfSave').onclick=()=>{if(![...document.querySelectorAll('.pdfReview')].every(x=>x.checked))return alert('Please review and tick each item before saving.');$('#pdfCheckModal').hidden=true;rawPdfSave?.()};
// Extend backups to V10 workspace keys.
const oldExportBackup=$('#exportBackup').onclick;$('#exportBackup').onclick=()=>{const includeSigs=confirm('Include saved signature images in this backup? Only do this for an authorised work device.');const keys=[TEMPLATE_KEY,TASK_KEY,LINK_KEY,NOTES_KEY,QUEUE_KEY,SNIPPET_KEY,PREF_KEY];const data={version:10,createdAt:new Date().toISOString(),storage:{}};for(const k of keys)data.storage[k]=localStorage.getItem(k);if(includeSigs){for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&/sig|signature/i.test(k))data.storage[k]=localStorage.getItem(k)}}const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='osama-automation-v10-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),500)};
// V10 dashboard extension.
const baseRenderDashboard=renderDashboard;renderDashboard=function(){baseRenderDashboard();const q=readLocal(QUEUE_KEY),open=q.filter(c=>c.status!=='Completed'),due=open.filter(c=>c.followup&&new Date(c.followup).getTime()<=Date.now());$('#dashboardGrid').insertAdjacentHTML('afterbegin',`<article class="dashCard"><span>Work Queue</span><strong>${open.length}</strong><p>${due.length} due/overdue • ${open.filter(c=>c.priority==='Urgent').length} urgent</p><button data-go-v10="queue">Open Queue</button></article><article class="dashCard"><span>Quick compose</span><strong>✉</strong><p>Templates + placeholders + snippets</p><button data-go-v10="composer">Compose Email</button></article><article class="dashCard"><span>Shift handover</span><strong>↗</strong><p>Generate outstanding-work summary</p><button data-go-v10="handover">Generate Handover</button></article>`);document.querySelectorAll('[data-go-v10]').forEach(b=>b.onclick=()=>setAppTab(b.dataset.goV10))};
// Modal backdrop close and Escape safety for new dialogs.
document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.hidden=true}));window.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.modal:not([hidden])').forEach(m=>m.hidden=true)}});
renderDashboard();

